"""SQLite repository for fraction questions."""

import json

from ..question.models import Question, QuestionType
from .database import Database


class QuestionRepository:
    """Persists and retrieves :class:`Question` records using parameterised SQL."""

    def __init__(self, db: Database):
        self.db = db

    @staticmethod
    def _to_question(row) -> Question:
        return Question(
            id=row["id"],
            prompt=row["prompt"],
            options=tuple(json.loads(row["options"])),
            correct_answer=row["correct_answer"],
            question_type=QuestionType(row["question_type"]),
        )

    def save(self, question: Question) -> Question:
        with self.db.connection() as conn:
            cursor = conn.execute(
                "INSERT INTO questions (prompt, options, correct_answer, question_type) VALUES (?, ?, ?, ?)",
                (question.prompt, json.dumps(list(question.options)), question.correct_answer, question.question_type.value),
            )
            new_id = cursor.lastrowid
        return Question(
            id=new_id,
            prompt=question.prompt,
            options=question.options,
            correct_answer=question.correct_answer,
            question_type=question.question_type,
        )

    def get(self, question_id: int):
        with self.db.connection() as conn:
            row = conn.execute(
                "SELECT id, prompt, options, correct_answer, question_type FROM questions WHERE id = ?",
                (question_id,),
            ).fetchone()
        return self._to_question(row) if row else None

    def list_all(self):
        with self.db.connection() as conn:
            rows = conn.execute(
                "SELECT id, prompt, options, correct_answer, question_type FROM questions ORDER BY id"
            ).fetchall()
        return [self._to_question(row) for row in rows]

    def update(self, question: Question) -> None:
        with self.db.connection() as conn:
            conn.execute(
                "UPDATE questions SET prompt = ?, options = ?, correct_answer = ?, question_type = ? WHERE id = ?",
                (question.prompt, json.dumps(list(question.options)), question.correct_answer, question.question_type.value, question.id),
            )

    def delete(self, question_id: int) -> bool:
        with self.db.connection() as conn:
            cursor = conn.execute("DELETE FROM questions WHERE id = ?", (question_id,))
        return cursor.rowcount > 0

    def count(self) -> int:
        with self.db.connection() as conn:
            row = conn.execute("SELECT COUNT(*) AS n FROM questions").fetchone()
        return row["n"]
