"""Game state machine for a single play session."""

from dataclasses import dataclass
from enum import Enum

from ..question.models import Question


class GameState(Enum):
    PLAYING = "playing"
    PAUSED = "paused"
    GAME_OVER = "game_over"


@dataclass(frozen=True)
class AnswerResult:
    is_correct: bool
    correct_answer: str
    score: int
    finished: bool


class Game:
    """Runs a loop over a list of questions, tracking score and state."""

    def __init__(self, questions):
        if not questions:
            raise ValueError("A game needs at least one question.")
        self._questions = list(questions)
        self._current_index = 0
        self._score = 0
        self._state = GameState.PLAYING

    @property
    def state(self):
        return self._state

    @property
    def score(self):
        return self._score

    @property
    def total_questions(self):
        return len(self._questions)

    @property
    def answered_count(self):
        return self._current_index

    def current_question(self):
        if self._state == GameState.GAME_OVER or self._current_index >= len(self._questions):
            return None
        return self._questions[self._current_index]

    def submit_answer(self, answer):
        if self._state == GameState.PAUSED:
            raise RuntimeError("Cannot answer while paused.")
        if self._state == GameState.GAME_OVER:
            raise RuntimeError("Game is already over.")
        question = self.current_question()
        if question is None:
            raise RuntimeError("No current question.")
        is_correct = question.is_correct(answer)
        if is_correct:
            self._score += 1
        self._current_index += 1
        finished = self._current_index >= len(self._questions)
        if finished:
            self._state = GameState.GAME_OVER
        return AnswerResult(is_correct=is_correct, correct_answer=question.correct_answer, score=self._score, finished=finished)

    def pause(self):
        if self._state == GameState.PLAYING:
            self._state = GameState.PAUSED

    def resume(self):
        if self._state == GameState.PAUSED:
            self._state = GameState.PLAYING

    def finish(self):
        self._state = GameState.GAME_OVER

    def is_finished(self):
        return self._state == GameState.GAME_OVER
